#include "ibmlegacy/cpu/system360_decoder.hpp"
namespace ibmlegacy::cpu {
static InstructionFormat fmt(const OpcodeInfo* p) noexcept { if(!p)return InstructionFormat::Unknown; if(p->format=="RR")return InstructionFormat::RR; if(p->format=="RX")return InstructionFormat::RX; if(p->format=="RS")return InstructionFormat::RS; if(p->format=="SI")return InstructionFormat::SI; if(p->format=="SS")return InstructionFormat::SS; return InstructionFormat::Unknown; }
DecodedInstruction decode_rr(std::uint8_t a,std::uint8_t b) noexcept { auto*p=find_system360_opcode(a); DecodedInstruction d{}; d.info=(p&&p->format=="RR")?p:nullptr; d.format=d.info?InstructionFormat::RR:InstructionFormat::Unknown; d.first=a; d.second=b; d.r1=b>>4U; d.r2=b&0x0FU; return d; }
DecodedInstruction decode_rx(std::uint8_t a,std::uint8_t b,std::uint8_t c,std::uint8_t e) noexcept { auto*p=find_system360_opcode(a); DecodedInstruction d{}; d.info=(p&&p->format=="RX")?p:nullptr; d.format=d.info?InstructionFormat::RX:InstructionFormat::Unknown; d.first=a;d.second=b;d.third=c;d.fourth=e;d.r1=b>>4U;d.x2=b&0x0FU;d.b2=c>>4U;d.d2=static_cast<std::uint16_t>(((c&0x0FU)<<8U)|e);d.displacement=d.d2;return d; }
DecodedInstruction decode_rs(std::uint8_t a,std::uint8_t b,std::uint8_t c,std::uint8_t e) noexcept { auto*p=find_system360_opcode(a); DecodedInstruction d{}; d.info=(p&&p->format=="RS")?p:nullptr;d.format=fmt(d.info);d.first=a;d.second=b;d.third=c;d.fourth=e;d.r1=b>>4U;d.r3=b&0x0FU;d.b2=c>>4U;d.d2=static_cast<std::uint16_t>(((c&0x0FU)<<8U)|e);d.displacement=d.d2;return d; }
DecodedInstruction decode_si(std::uint8_t a,std::uint8_t b,std::uint8_t c) noexcept { auto*p=find_system360_opcode(a);DecodedInstruction d{};d.info=(p&&p->format=="SI")?p:nullptr;d.format=fmt(d.info);d.first=a;d.second=b;d.third=c;d.i2=b;d.b1=c>>4U;d.d1=static_cast<std::uint16_t>((c&0x0FU)<<8U);return d; }
DecodedInstruction decode_ss(std::uint8_t a,std::uint8_t b,std::uint8_t c,std::uint8_t d8,std::uint8_t e,std::uint8_t f) noexcept { auto*p=find_system360_opcode(a);DecodedInstruction d{};d.info=(p&&p->format=="SS")?p:nullptr;d.format=fmt(d.info);d.first=a;d.second=b;d.third=c;d.fourth=d8;d.l1=(b>>4U)&0x0FU;d.l2=b&0x0FU;d.b1=c>>4U;d.d1=static_cast<std::uint16_t>(((c&0x0FU)<<8U)|d8);d.b2=e>>4U;d.d2=static_cast<std::uint16_t>(((e&0x0FU)<<8U)|f);return d; }
}
